import CoreVideo
import Foundation

/// 🐱 How trustworthy `presentationTime` is. Velocities are only computed from `.source` timestamps by default,
/// 🐱 because network arrival times include Wi-Fi jitter that would show up as fake velocity noise.
public enum TimestampQuality: String, Codable, Sendable {
    /// 🐱 Timestamp generated by the camera / file at capture time, unit verified.
    case source
    /// 🐱 Camera timestamp whose unit is not verified yet (first few frames of a stream).
    case provisional
    /// 🐱 Host arrival time, used only when the source gives no usable timestamp.
    case hostArrival
    /// 🐱 Synthetic, exact (TestVideoSource).
    case synthetic
}

/// 🐱 Host-side timing of one frame, all on `HostClock`.
public struct FrameTiming: Sendable, Codable, Equatable {
    /// 🐱 Raw timestamp exactly as delivered by the source (camera ticks, file timescale value...).
    public var sourceTimestampRaw: Int64?
    /// 🐱 When the last byte of this frame arrived from the network / file / device.
    public var receivedHostTime: Double
    /// 🐱 When the picture was known to be complete and handed to the decoder. In safe assembly mode this is
    /// 🐱 when the next picture's first packet arrived, so `assembled - received` is the assembly wait.
    public var assembledHostTime: Double
    /// 🐱 When the decoder produced the pixel buffer.
    public var decodedHostTime: Double

    public init(sourceTimestampRaw: Int64?, receivedHostTime: Double, assembledHostTime: Double? = nil, decodedHostTime: Double) {
        self.sourceTimestampRaw = sourceTimestampRaw
        self.receivedHostTime = receivedHostTime
        self.assembledHostTime = assembledHostTime ?? receivedHostTime
        self.decodedHostTime = decodedHostTime
    }
}

/// 🐱 One decoded frame. Pixel data is always bi-planar 4:2:0 or single-plane 8-bit luma, so the analysis can read
/// 🐱 plane 0 as the luminance image without any colour conversion.
public final class VideoFrame: @unchecked Sendable {
    /// 🐱 Sequential index assigned by the source, starting at 0 after each `startPreview()`.
    public let index: Int
    public let pixelBuffer: CVPixelBuffer
    /// 🐱 Seconds on the source's own timeline (camera clock, file timeline). Monotonic within a stream segment.
    public let presentationTime: Double
    public let timestampQuality: TimestampQuality
    /// 🐱 Increments whenever the source timeline restarts (stream restart, file loop). Trackers must reset on change.
    public let segment: Int
    public let timing: FrameTiming

    public var width: Int { CVPixelBufferGetWidth(pixelBuffer) }
    public var height: Int { CVPixelBufferGetHeight(pixelBuffer) }

    public init(index: Int, pixelBuffer: CVPixelBuffer, presentationTime: Double,
                timestampQuality: TimestampQuality, segment: Int, timing: FrameTiming) {
        self.index = index
        self.pixelBuffer = pixelBuffer
        self.presentationTime = presentationTime
        self.timestampQuality = timestampQuality
        self.segment = segment
        self.timing = timing
    }
}
